/* All four summary cards remain children of the map view. */
@media screen{
  #view-network-map > .rete-network-summary-grid{
    display:grid!important;
    grid-template-columns:repeat(2,minmax(0,1fr))!important;
    gap:14px;
    width:100%;
    min-width:0;
    max-width:100%;
    align-items:start;
  }
  #view-network-map > .rete-network-summary-grid > .rete-network-summary-card{
    position:relative;
    inset:auto;
    z-index:auto;
    min-width:0;
    max-width:100%;
    width:100%;
    height:auto;
    overflow:hidden;
    align-self:start;
  }
  #view-network-map .rete-network-summary-card canvas{
    display:block;
    width:100%!important;
    max-width:100%;
    height:auto!important;
  }
  #view-network-map .rete-network-summary-card .table-wrap{
    max-width:100%;
    max-height:420px;
    overflow:auto;
  }
  #view-network-map .rete-network-summary-card table{
    min-width:620px;
    table-layout:auto;
  }
  #view-network-map [data-rete-network-note]{
    margin-top:10px;
    padding:10px 12px;
    border:1px solid #d5e0ec;
    border-radius:9px;
    background:#f4f8fc;
    color:#315477;
    font-size:11px;
    line-height:1.5;
  }
}
@media screen and (max-width:1000px){
  #view-network-map > .rete-network-summary-grid{
    grid-template-columns:minmax(0,1fr)!important;
  }
}

