<!-- Nonblocking shared integrations: run only after page load. -->

function formCircuitChoices() {return uniq(ACTIVE_MAINTENANCE_DATA.map(x=>`${x.voltage} ${x.feeder}`).filter(x=>!x.includes("No 33 kV feeder")&&!x.includes("No 11 kV feeder")));}

/* Use the responsibility register for assignments and the network register
   for source links. Never substitute an unrelated source for a missing link. */
function reteNetworkKey(value){
  return String(value||"").toLowerCase().replace(/[^a-z0-9]/g,"");
}
function reteNetworkStationKey(value){
  return reteNetworkKey(String(value||"")
    .replace(/\b\d+(?:\/\d+)*\s*kV\b/gi,"")
    .replace(/\bArea Control Cent(?:er|re)\b/gi,"")
    .replace(/\b(?:Injection Substation|Substation|Station)\b/gi,""));
}
function reteNetworkSourceState(source){
  const wanted=reteNetworkStationKey(source);
  const listed=SUBSTATION_DATA.find(row=>reteNetworkStationKey(row.name)===wanted)?.state;
  if(listed)return listed;
  // A transmission source can be present in the network register but absent
  // from SUBSTATION_DATA (for example Gagarawa). Resolve its state through
  // exact recorded feeder joins, only when every matching state agrees.
  const injection=typeof INJECTION_STATIONS!=="undefined"?INJECTION_STATIONS:[];
  const transmission=typeof TRANSMISSION_FEEDERS!=="undefined"?TRANSMISSION_FEEDERS:[];
  const feeder33=new Set(transmission.filter(row=>row.source===source).map(row=>reteNetworkKey(row.name)));
  const feeder11=new Set();
  for(const row of injection.filter(item=>item.source===source)){
    feeder33.add(reteNetworkKey(row.sourceFeeder));
    for(const [name] of row.other33||[])feeder33.add(reteNetworkKey(name));
    for(const [name] of row.feeders||[])feeder11.add(reteNetworkKey(name));
  }
  const states=uniq(ALL_MAINTENANCE_DATA.filter(row=>(row.voltage==="33 kV"?feeder33:row.voltage==="11 kV"?feeder11:new Set()).has(reteNetworkKey(row.feeder))).map(row=>row.state));
  return states.length===1?states[0]:"";
}
function reteNetworkLinks(assignment){
  const injection=typeof INJECTION_STATIONS!=="undefined"?INJECTION_STATIONS:[];
  const transmission=typeof TRANSMISSION_FEEDERS!=="undefined"?TRANSMISSION_FEEDERS:[];
  const wanted=reteNetworkKey(assignment.feeder),links=[];
  if(!wanted||/^No\s/i.test(assignment.feeder||""))return links;
  for(const row of injection){
    if(reteNetworkSourceState(row.source)!==assignment.state)continue;
    const feeder11=assignment.voltage==="11 kV"&&(row.feeders||[]).find(([name])=>reteNetworkKey(name)===wanted);
    const source33=assignment.voltage==="33 kV"&&reteNetworkKey(row.sourceFeeder)===wanted;
    const other33=assignment.voltage==="33 kV"&&(row.other33||[]).find(([name])=>reteNetworkKey(name)===wanted);
    if(feeder11||source33||other33)links.push({
      injectionId:row.id,station:row.station,source:row.source,
      sourceFeeder:row.sourceFeeder,feeder:feeder11?.[0]||other33?.[0]||row.sourceFeeder,
      kind:feeder11?"11":source33?"source33":"other33"
    });
  }
  if(assignment.voltage==="33 kV")for(const row of transmission){
    if(reteNetworkSourceState(row.source)!==assignment.state||reteNetworkKey(row.name)!==wanted)continue;
    links.push({station:"",source:row.source,sourceFeeder:row.name,feeder:row.name,kind:"transmission33"});
    for(const station of row.destinations||[])links.push({station,source:row.source,sourceFeeder:row.name,feeder:row.name,kind:"transmission33"});
  }
  return links;
}
function reteNetworkCatalog(){
  return ACTIVE_MAINTENANCE_DATA.filter(row=>row.feeder&&!/^(?:No\s|[—-]\s*Blank)/i.test(row.feeder))
    .map(row=>({...row,links:reteNetworkLinks(row)}));
}
function reteScopedInjectionRows(){
  const injection=typeof INJECTION_STATIONS!=="undefined"?INJECTION_STATIONS:[];
  const catalog=reteNetworkCatalog();
  return injection.flatMap(row=>{
    const links=catalog.flatMap(assignment=>assignment.links).filter(link=>link.injectionId===row.id);
    if(!links.some(link=>link.kind==="11"||link.kind==="source33"))return [];
    const ownsSupply=links.some(link=>link.kind==="source33");
    return [{...row,
      feeders:(row.feeders||[]).filter(([name])=>ownsSupply||links.some(link=>link.kind==="11"&&reteNetworkKey(link.feeder)===reteNetworkKey(name))),
      other33:(row.other33||[]).filter(([name])=>links.some(link=>link.kind==="other33"&&reteNetworkKey(link.feeder)===reteNetworkKey(name)))
    }];
  });
}
function reteScopedTransmissionRows(){
  const transmission=typeof TRANSMISSION_FEEDERS!=="undefined"?TRANSMISSION_FEEDERS:[];
  const injection=typeof INJECTION_STATIONS!=="undefined"?INJECTION_STATIONS:[];
  const catalog=reteNetworkCatalog(),scopedInjection=reteScopedInjectionRows();
  const owns= row=>catalog.some(assignment=>assignment.voltage==="33 kV"&&assignment.state===reteNetworkSourceState(row.source)&&reteNetworkKey(assignment.feeder)===reteNetworkKey(row.name));
  const supplies= row=>scopedInjection.some(station=>station.source===row.source&&reteNetworkKey(station.sourceFeeder)===reteNetworkKey(row.name));
  const rows=transmission.filter(row=>owns(row)||supplies(row)).map(row=>({...row}));
  // A TE needs the recorded upstream 33 kV supply as map context. This does
  // not add that feeder to the TE's own maintenance or eForm assignments.
  for(const station of scopedInjection){
    if(!rows.some(row=>row.source===station.source&&reteNetworkKey(row.name)===reteNetworkKey(station.sourceFeeder))){
      rows.push({id:"RETE-SUPPLY-"+station.id,source:station.source,transformer:station.sourceTr,
        name:station.sourceFeeder,band:"",destinations:[station.station],classification:"INJECTION SUPPLY",special:""});
    }
  }
  // Some 33 kV feeders are recorded only in the injection register's other33.
  for(const assignment of catalog.filter(row=>row.voltage==="33 kV"))for(const link of assignment.links.filter(item=>item.kind==="other33")){
    if(rows.some(row=>row.source===link.source&&reteNetworkKey(row.name)===reteNetworkKey(link.feeder)))continue;
    const station=injection.find(row=>row.id===link.injectionId);
    rows.push({id:"RETE-OTHER-"+link.injectionId+"-"+reteNetworkKey(link.feeder),source:link.source,
      transformer:station?.sourceTr||"",name:link.feeder,band:(station?.other33||[]).find(([name])=>name===link.feeder)?.[1]||"",
      destinations:[],classification:"DIRECT 33KV / NO INJECTION",special:"Recorded in injection register"});
  }
  return rows;
}
window.KEDCO_RETE_SCOPED_NETWORK={
  version:"20261002-network-v1",catalog:reteNetworkCatalog,
  injectionRows:reteScopedInjectionRows,transmissionRows:reteScopedTransmissionRows,
  sourceNames:()=>uniq([...reteScopedTransmissionRows(),...reteScopedInjectionRows()].map(row=>row.source)),
  unresolved:()=>reteNetworkCatalog().filter(row=>!row.links.length)
};

  if(refresh&&document.readyState!=="loading")reteRefreshScopeViews();
  window.dispatchEvent(new CustomEvent("kedco:rete-scope-changed"));
}

