function setNetworkChoices(control, values, placeholder){
  if(!control)return;
  const previous=control.value;
  const entries=[{value:"",label:placeholder},...unique(values).map(value=>({value,label:value}))];
  if(control.options.length!==entries.length||entries.some((item,index)=>control.options[index]?.value!==item.value||control.options[index]?.textContent!==item.label)){
    control.innerHTML=entries.map(item=>`<option value="${escNM(item.value)}">${escNM(item.label)}</option>`).join("");
  }
  control.value=entries.some(item=>item.value===previous)?previous:"";
  control.disabled=entries.length===1;
}
function updateNetworkScopeNote(){
  const grid=document.querySelector("#view-network-map .network-map-filter-grid");
  if(!grid)return;
  let note=document.querySelector("[data-rete-network-note]");
  if(!note){note=document.createElement("p");note.dataset.reteNetworkNote="";note.className="no-print";note.setAttribute("role","status");grid.after(note);}
  const catalog=reteNetworkCatalog(),missing=catalog.filter(row=>!row.links.length);
  const label=[RETE_SCOPE.role,RETE_SCOPE.region,RETE_SCOPE.unit].filter(Boolean).join(" | ");
  note.textContent=label+" — "+catalog.length+" registered feeder assignment(s)."+
    (missing.length?" Source/station link not recorded for: "+missing.map(row=>row.voltage+" "+row.feeder).join(", ")+". These feeders remain available in the eForms.":" Map sources and feeders follow this assignment.");
}
